insert into ajustes (clave, valor, descripcion) values
  ('mensaje_base', '{"puntos":["Introduce Moche Verde: Peruvian-inspired food at music festivals in Portugal and Spain.","Explain the concept and the food we serve.","We deliver a high-quality product.","We do not make customers wait: they want to make the most of their time watching their favourite artists, without compromising on good service."],"incluir":["web","instagram","telefono"]}'::jsonb, 'Key points for outreach emails. Claude writes a personalised email per festival from these.'),
  ('contacto_moche_verde', '{"web":"mocheverde.com","instagram":"@moche.verde","telefono":"+351 916 273 966"}'::jsonb, 'Contact details included in emails. Phone is Rodrigo''s (Portuguese speaker).'),
  ('dias_recontacto', '2'::jsonb, 'Business days (Mon–Fri) without a reply before the next follow-up.'),
  ('revisiones_outlook', '{"zona_horaria":"Europe/Lisbon","horas":["10:00","15:00","18:00"]}'::jsonb, 'When Claude checks the Outlook mailbox and processes requests.');
